        case "message": self = .message(try MessageResource(from: decoder))
        case "launch": self = .launch(try LaunchResource(from: decoder))
        case "launch-variant": self = .launchVariant(try LaunchVariantResource(from: decoder))
        case "launch-decision": self = .launchDecision(try LaunchDecisionResource(from: decoder))
        case "launch-approval": self = .launchApproval(try LaunchApprovalResource(from: decoder))
