    public let id: String; public let sequence: UInt64; public let revision: UInt; public let timestamp: String; public let role: TimelineRole; public let type: TimelineType; public let isFinal: Bool; public let body: TimelineBody
    enum CodingKeys: String, CodingKey { case id, sequence, revision, timestamp, role, type, isFinal = "final", body }
    public init(from decoder: Decoder) throws {
        let values = try decoder.container(keyedBy: CodingKeys.self)
        id = try values.decode(String.self, forKey: .id); sequence = try values.decode(UInt64.self, forKey: .sequence); revision = try values.decode(UInt.self, forKey: .revision); timestamp = try values.decode(String.self, forKey: .timestamp); role = try values.decode(TimelineRole.self, forKey: .role); type = try values.decode(TimelineType.self, forKey: .type); isFinal = try values.decode(Bool.self, forKey: .isFinal)
        body = switch type { case .message: .message(try values.decode(TimelineMessageBody.self, forKey: .body)); case .content: .content(try values.decode(TimelineContentBody.self, forKey: .body)); case .toolCall: .toolCall(try values.decode(TimelineToolCallBody.self, forKey: .body)); case .toolResult: .toolResult(try values.decode(TimelineToolResultBody.self, forKey: .body)); case .status: .status(try values.decode(TimelineStatusBody.self, forKey: .body)); case .error: .error(try values.decode(TimelineErrorBody.self, forKey: .body)); case .usage: .usage(try values.decode(TimelineUsageBody.self, forKey: .body)); case .redaction: .redaction(try values.decode(TimelineRedactionBody.self, forKey: .body)); case .truncation: .truncation(try values.decode(TimelineTruncationBody.self, forKey: .body)) }
    }
    public func encode(to encoder: Encoder) throws {
        var values = encoder.container(keyedBy: CodingKeys.self); try values.encode(id, forKey: .id); try values.encode(sequence, forKey: .sequence); try values.encode(revision, forKey: .revision); try values.encode(timestamp, forKey: .timestamp); try values.encode(role, forKey: .role); try values.encode(type, forKey: .type); try values.encode(isFinal, forKey: .isFinal)
        switch body { case .message(let value): try values.encode(value, forKey: .body); case .content(let value): try values.encode(value, forKey: .body); case .toolCall(let value): try values.encode(value, forKey: .body); case .toolResult(let value): try values.encode(value, forKey: .body); case .status(let value): try values.encode(value, forKey: .body); case .error(let value): try values.encode(value, forKey: .body); case .usage(let value): try values.encode(value, forKey: .body); case .redaction(let value): try values.encode(value, forKey: .body); case .truncation(let value): try values.encode(value, forKey: .body) }
    }
}
